import { useDeferredValue, useState } from 'react';
import { AlertTriangle, Beer, PawPrint, Search } from 'lucide-react';
import { formatMoney, PAYMENT_METHODS, PENALTIES, ROOM_CATEGORIES, ROOM_STATUSES, selectAccountBalance, selectClientName } from '../../domain/hotelModel';
import { useHotel } from '../../state/hotelContext';
import { Drawer, PrototypeNotice, Tabs, TabPanel } from '../ui/Overlay';
import { executeWithFeedback } from '../ui/actionFeedback';
import { DataTable, DetailGrid, EmptyState, Kpi, MetricStrip, PageHeader, SectionHeader, StatusBadge } from './SharedViewParts';

const formatDateTime = (value) => value ? new Date(value).toLocaleString('es-PE') : 'No registrado';
const availableStock = (item) => item.stock - item.reserved;
const nextIncidentStatus = (status) => ({ Pendiente: 'Asignada', Asignada: 'En proceso', 'En proceso': 'Resuelta', Resuelta: 'Cerrada' })[status] || null;
const moduleRoutes = { Contratos: 'contratos', Reservas: 'reservas', 'Check-in': 'checkin-checkout', 'Check-out': 'checkin-checkout', Pagos: 'finanzas', Clientes: 'clientes', Limpieza: 'limpieza', Mantenimiento: 'mantenimiento', Incidencias: 'incidencias', Inventario: 'inventario', 'Pedidos QR': 'pedidos-qr', Eventos: 'eventos', 'Zonas recreativas': 'recreacion' };

export function ContractsView() {
  const { state } = useHotel();
  const [query, setQuery] = useState('');
  const [status, setStatus] = useState('Todos');
  const [selectedId, setSelectedId] = useState(null);
  const deferred = useDeferredValue(query.toLowerCase());
  const contracts = state.contracts.filter((item) => `${item.id} ${item.reservationId} ${selectClientName(state, item.clientId)} ${item.roomId}`.toLowerCase().includes(deferred) && (status === 'Todos' || item.status === status));
  const selected = state.contracts.find((item) => item.id === selectedId);
  const reservation = state.reservations.find((item) => item.id === selected?.reservationId);
  const client = state.clients.find((item) => item.id === selected?.clientId);
  const room = state.rooms.find((item) => item.id === selected?.roomId);
  const payment = state.payments.find((item) => item.reservationId === selected?.reservationId);
  return <div className="view-container">
    <PageHeader metadata="Versionado y trazabilidad" title="Contratos de hospedaje" description="Unión de cliente, reserva, habitación, condiciones económicas y versiones contractuales." />
    <MetricStrip items={[{ label: 'Contratos', value: state.contracts.length }, { label: 'Pendientes de firma', value: state.contracts.filter((item) => item.status === 'Pendiente de firma').length }, { label: 'Firmados', value: state.contracts.filter((item) => item.status === 'Firmado').length }, { label: 'Finalizados', value: state.contracts.filter((item) => item.status === 'Finalizado').length }, { label: 'Versiones conservadas', value: state.contracts.reduce((sum, item) => sum + item.versions.length, 0) }]} />
    <div className="filter-bar"><label className="search-label"><Search size={16} /><input aria-label="Buscar contratos" placeholder="Código, reserva, cliente o habitación" value={query} onChange={(event) => setQuery(event.target.value)} /></label><label>Estado<select value={status} onChange={(event) => setStatus(event.target.value)}><option>Todos</option>{[...new Set(state.contracts.map((item) => item.status))].map((item) => <option key={item}>{item}</option>)}</select></label><span className="filter-result">{contracts.length} contratos</span></div>
    <DataTable caption="Contratos y documentos firmados declarados" columns={['Contrato', 'Reserva', 'Cliente', 'Habitación', 'Versión', 'Generado', 'Documento firmado', 'Estado', 'Detalle']} emptyTitle="Sin contratos">{contracts.length ? contracts.map((item) => <tr key={item.id}><td><strong>{item.id}</strong></td><td>{item.reservationId}</td><td>{selectClientName(state, item.clientId)}</td><td>{item.roomId}</td><td>V{item.version}</td><td>{formatDateTime(item.generatedAt)}</td><td>{item.signedDocument || 'Pendiente'}</td><td><StatusBadge>{item.status}</StatusBadge></td><td><button className="btn btn-sm btn-outline" onClick={() => setSelectedId(item.id)}>Ver contrato</button></td></tr>) : null}</DataTable>
    <Drawer open={Boolean(selected)} onClose={() => setSelectedId(null)} title={selected?.id || 'Contrato'} description={selected ? `Reserva ${selected.reservationId} · V${selected.version}` : ''}>{selected ? <div className="detail-stack">
      <section><SectionHeader eyebrow="Partes" title="Cliente y contratación" /><DetailGrid items={[{ label: 'Cliente', value: client?.name, detail: `${client?.documentType} ${client?.documentNumber}` }, { label: 'Contacto', value: client?.phone, detail: client?.email }, { label: 'Dirección y nacionalidad', value: client?.address, detail: client?.nationality }, { label: 'Habitación', value: `${room?.id} · ${reservation?.category}`, detail: `Piso ${room?.floor}` }, { label: 'Estadía contratada', value: `${reservation?.checkIn} a ${reservation?.checkOut}`, detail: `${reservation?.nights} noche(s)` }, { label: 'Huéspedes', value: reservation?.guests, detail: `${reservation?.extraGuests} adicionales · ${reservation?.petIds.length} mascota(s)` }]} /></section>
      <section><SectionHeader eyebrow="Condiciones económicas" title="Importes y servicios" /><DetailGrid items={[{ label: 'Precio por noche', value: formatMoney(reservation?.nightlyRate) }, { label: 'Total', value: formatMoney(reservation?.total) }, { label: 'Adelanto', value: formatMoney(reservation?.advance), detail: `${reservation?.paymentMethod} · ${payment?.operationNumber || 'Sin operación'}` }, { label: 'Saldo', value: formatMoney(reservation?.balance) }, { label: 'Crédito reembolsable', value: formatMoney(reservation?.refundableCredit || 0), detail: reservation?.refundableCredit > 0 ? 'Excedente de adelanto preservado' : 'Sin excedente' }, { label: 'Servicios', value: reservation?.services.join(', ') || 'Sin adicionales' }, { label: 'Llegada límite', value: reservation?.arrivalLimit }]} /></section>
      <section><SectionHeader eyebrow="Trazabilidad" title="Línea de versiones" /><ol className="version-timeline">{selected.versions.map((item) => <li key={`${item.version}-${item.reason}`}><strong>Versión {item.version}</strong><span>{item.reason}</span></li>)}</ol></section>
      <section><SectionHeader eyebrow="Referencia del proyecto" title="Políticas que debe contener" /><div className="policy-grid"><article><strong>Hospedaje</strong><span>Check-in/out, permanencia, ruido, visitas, bienes y obligaciones.</span></article><article><strong>Servicios</strong><span>Mascotas, personas adicionales, cochera, piscina y mirador.</span></article><article><strong>Modificaciones</strong><span>Retiro anticipado, ampliación, adendas, cancelación y no presentación.</span></article><article><strong>Penalidades</strong><span>Daños, llaves, limpieza extraordinaria y evidencia requerida.</span></article></div></section>
      <PrototypeNotice>vista previa, PDF, impresión, QR contractual, firma digital, correo, WhatsApp y carga segura de archivos no están integrados. El texto mostrado es referencia operativa, no un documento legal emitido.</PrototypeNotice>
    </div> : null}</Drawer>
  </div>;
}

export function FinanceView() {
  const { state } = useHotel();
  const [tab, setTab] = useState('pagos');
  const [method, setMethod] = useState('Todos');
  const totalPayments = state.payments.reduce((sum, item) => sum + item.amount, 0);
  const openAccounts = state.accounts.filter((item) => item.status === 'Abierta');
  const closedAccounts = state.accounts.filter((item) => item.status === 'Cerrada');
  const filteredPayments = state.payments.filter((item) => method === 'Todos' || item.method === method);
  return <div className="view-container">
    <PageHeader metadata="Pagos y documentos internos" title="Finanzas" description="Métodos de pago, saldos de habitación, cuentas cerradas y referencias documentales." />
    <MetricStrip items={[{ label: 'Pagos registrados', value: formatMoney(totalPayments) }, { label: 'Cuentas abiertas', value: openAccounts.length }, { label: 'Saldo abierto', value: formatMoney(openAccounts.reduce((sum, item) => sum + selectAccountBalance(item), 0)) }, { label: 'Cuentas cerradas', value: closedAccounts.length }, { label: 'Documentos internos', value: state.documents.length }]} />
    <Tabs label="Información financiera" activeTab={tab} onChange={setTab} tabs={[{ id: 'pagos', label: 'Pagos' }, { id: 'cuentas', label: 'Cuentas' }, { id: 'documentos', label: 'Documentos' }]} />
    <TabPanel active={tab === 'pagos'} label="Pagos registrados"><div className="filter-bar"><label>Método<select value={method} onChange={(event) => setMethod(event.target.value)}><option>Todos</option>{PAYMENT_METHODS.map((item) => <option key={item}>{item}</option>)}</select></label><span className="filter-result">{filteredPayments.length} pagos · {formatMoney(filteredPayments.reduce((sum, item) => sum + item.amount, 0))}</span></div><DataTable caption="Pagos registrados en la sesión" columns={['Pago', 'Fecha', 'Cliente', 'Concepto', 'Reserva / cuenta / pedido', 'Método', 'Operación', 'Responsable', 'Importe', 'Estado']}>{filteredPayments.length ? filteredPayments.map((item) => <tr key={item.id}><td>{item.id}</td><td>{formatDateTime(item.createdAt)}</td><td>{selectClientName(state, item.clientId)}</td><td>{item.concept}</td><td>{item.reservationId || item.accountId || item.orderId || 'Sin referencia'}</td><td>{item.method}</td><td>{item.operationNumber}</td><td>{item.responsible}</td><td>{formatMoney(item.amount)}</td><td><StatusBadge>{item.status}</StatusBadge></td></tr>) : null}</DataTable></TabPanel>
    <TabPanel active={tab === 'cuentas'} label="Cuentas de habitación"><div className="operation-cards">{state.accounts.map((account) => { const stay = state.stays.find((item) => item.id === account.stayId); return <article className="card operation-card" key={account.id}><div className="row-between"><div><span className="eyebrow">{account.id} · Hab. {account.roomId}</span><h3>{selectClientName(state, stay?.clientId)}</h3></div><StatusBadge>{account.status}</StatusBadge></div><section><SectionHeader title="Cargos" /><div className="account-lines">{account.charges.map((charge) => <span key={charge.id}>{charge.concept}<strong>{formatMoney(charge.amount)}</strong></span>)}</div></section><section><SectionHeader title="Pagos aplicados" /><div className="account-lines">{account.payments.length ? account.payments.map((payment) => <span className="payment-line" key={payment.id}>{payment.id} · {payment.method}<strong>− {formatMoney(payment.amount)}</strong></span>) : <span>Sin pagos aplicados<strong>{formatMoney(0)}</strong></span>}</div></section><div className="operation-total"><span>Saldo</span><strong>{formatMoney(selectAccountBalance(account))}</strong></div>{account.refundableCredit > 0 ? <div className="alert-banner alert-banner-warning">Crédito reembolsable preservado: {formatMoney(account.refundableCredit)}</div> : null}</article>; })}</div></TabPanel>
    <TabPanel active={tab === 'documentos'} label="Documentos internos"><DataTable caption="Referencias documentales internas, no comprobantes fiscales" columns={['Documento', 'Tipo', 'Referencia', 'Estado interno', 'Situación fiscal']}>{state.documents.length ? state.documents.map((item) => <tr key={item.id}><td>{item.id}</td><td>{item.type}</td><td>{item.referenceId}</td><td><StatusBadge>{item.status}</StatusBadge></td><td><StatusBadge>{item.fiscalStatus}</StatusBadge></td></tr>) : null}</DataTable><PrototypeNotice>los documentos son etiquetas internas. No se emiten boletas, facturas, recibos, PDF certificados ni envíos externos.</PrototypeNotice></TabPanel>
  </div>;
}

export function NotificationsView({ navigate }) {
  const { state, dispatch } = useHotel();
  const [read, setRead] = useState('Todas');
  const [type, setType] = useState('Todos');
  const [module, setModule] = useState('Todos');
  const records = state.notifications.filter((item) => (read === 'Todas' || item.read === (read === 'Leídas')) && (type === 'Todos' || item.type === type) && (module === 'Todos' || item.route === module));
  const groups = [...new Set(records.map((item) => item.route))];
  return <div className="view-container"><PageHeader metadata="Canal interno local" title="Notificaciones" description="Bandeja por lectura, tipo y módulo de destino; no confirma mensajería externa." action={<button className="btn btn-outline" disabled={!state.notifications.some((item) => !item.read)} onClick={() => dispatch({ type: 'NOTIFICATIONS_READ_ALL' })}>Marcar todas como leídas</button>} /><MetricStrip items={[{ label: 'Total', value: state.notifications.length }, { label: 'Sin leer', value: state.notifications.filter((item) => !item.read).length }, { label: 'Módulos destino', value: new Set(state.notifications.map((item) => item.route)).size }, { label: 'Canales externos', value: 'No integrados' }]} /><div className="filter-bar"><label>Lectura<select value={read} onChange={(event) => setRead(event.target.value)}><option>Todas</option><option>Sin leer</option><option>Leídas</option></select></label><label>Tipo<select value={type} onChange={(event) => setType(event.target.value)}><option>Todos</option>{[...new Set(state.notifications.map((item) => item.type))].map((item) => <option key={item}>{item}</option>)}</select></label><label>Módulo<select value={module} onChange={(event) => setModule(event.target.value)}><option>Todos</option>{[...new Set(state.notifications.map((item) => item.route))].map((item) => <option key={item} value={item}>{item}</option>)}</select></label><span className="filter-result">{records.length} notificaciones</span></div>{groups.length ? groups.map((route) => <section key={route} aria-labelledby={`notifications-${route}`}><SectionHeader id={`notifications-${route}`} eyebrow="Destino" title={route} description={`${records.filter((item) => item.route === route).length} mensaje(s)`} /><div className="record-list">{records.filter((item) => item.route === route).map((item) => <article className="card" key={item.id}><div><strong>{item.title}</strong><span>{item.description}</span><small>Tipo: {item.type} · canal interno</small></div><div className="inline-actions"><StatusBadge>{item.read ? 'Leída' : 'Pendiente'}</StatusBadge><button className="btn btn-sm btn-outline" onClick={() => navigate(item.route)}>Abrir módulo</button></div></article>)}</div></section>) : <EmptyState title="Sin notificaciones para estos filtros" description="La bandeja no tiene registros coincidentes; esto no implica que se hayan enviado mensajes externos." />}<PrototypeNotice>Topbar y esta vista cuentan los mismos registros internos. Correo y WhatsApp permanecen sin integración.</PrototypeNotice></div>;
}

export function EvidenceView() {
  const { state } = useHotel();
  const [source, setSource] = useState('Todas');
  const [roomId, setRoomId] = useState('Todas');
  const [status, setStatus] = useState('Todos');
  const [query, setQuery] = useState('');
  const evidence = [
    ...state.cleaningTasks.flatMap((task) => task.evidence.map((detail, index) => ({ id: `${task.id}-${index}`, source: 'Limpieza', kind: 'Foto o video declarado', referenceId: task.id, roomId: task.roomId, detail, status: task.status }))),
    ...state.maintenanceTickets.flatMap((ticket) => ticket.evidence.map((detail, index) => ({ id: `${ticket.id}-${index}`, source: 'Mantenimiento', kind: 'Evidencia técnica declarada', referenceId: ticket.id, roomId: ticket.roomId, detail, status: ticket.status }))),
    ...state.incidents.flatMap((incident) => incident.evidence.map((detail, index) => ({ id: `${incident.id}-${index}`, source: 'Incidencias', kind: 'Evidencia de incidencia', referenceId: incident.id, roomId: incident.roomId, detail, status: incident.status }))),
    ...state.contracts.filter((contract) => contract.signedDocument).map((contract) => ({ id: `${contract.id}-signed`, source: 'Contratos', kind: 'Documento firmado declarado', referenceId: contract.id, roomId: contract.roomId, detail: contract.signedDocument, status: contract.status })),
  ].map((item) => {
    const stay = state.stays.find((entry) => entry.roomId === item.roomId);
    const reservation = state.reservations.find((entry) => entry.id === stay?.reservationId || (item.source === 'Contratos' && entry.contractId === item.referenceId));
    return { ...item, stayId: stay?.id, reservationId: reservation?.id, clientId: stay?.clientId || reservation?.clientId };
  });
  const records = evidence.filter((item) => (source === 'Todas' || item.source === source) && (roomId === 'Todas' || item.roomId === roomId) && (status === 'Todos' || item.status === status) && `${item.referenceId} ${item.detail}`.toLowerCase().includes(query.toLowerCase()));
  return <div className="view-container"><PageHeader metadata="Metadatos, no archivos almacenados" title="Evidencias" description="Fuentes operativas con habitación, referencia, tipo y relaciones resolubles de huésped y estadía." /><MetricStrip items={[...new Set(evidence.map((item) => item.source))].map((item) => ({ label: item, value: evidence.filter((entry) => entry.source === item).length }))} /><div className="filter-bar"><label className="search-label"><Search size={16} /><input aria-label="Buscar evidencia" placeholder="Referencia o descripción" value={query} onChange={(event) => setQuery(event.target.value)} /></label><label>Fuente<select value={source} onChange={(event) => setSource(event.target.value)}><option>Todas</option>{[...new Set(evidence.map((item) => item.source))].map((item) => <option key={item}>{item}</option>)}</select></label><label>Habitación<select value={roomId} onChange={(event) => setRoomId(event.target.value)}><option>Todas</option>{[...new Set(evidence.map((item) => item.roomId).filter(Boolean))].map((item) => <option key={item}>{item}</option>)}</select></label><label>Estado<select value={status} onChange={(event) => setStatus(event.target.value)}><option>Todos</option>{[...new Set(evidence.map((item) => item.status))].map((item) => <option key={item}>{item}</option>)}</select></label></div><DataTable caption="Referencias de evidencia declaradas por módulo" columns={['Fuente', 'Tipo', 'Referencia', 'Habitación', 'Cliente / estadía / reserva', 'Descripción', 'Estado']} emptyTitle="Sin evidencias declaradas">{records.length ? records.map((item) => <tr key={item.id}><td>{item.source}</td><td>{item.kind}</td><td>{item.referenceId}</td><td>{item.roomId || 'No aplica'}</td><td>{selectClientName(state, item.clientId)}<br /><small>{item.stayId || 'Sin estadía'} · {item.reservationId || 'Sin reserva'}</small></td><td>{item.detail}</td><td><StatusBadge>{item.status}</StatusBadge></td></tr>) : null}</DataTable><PrototypeNotice>no hay almacenamiento seguro, miniaturas, descarga ni comparación real de fotografías, videos o PDF.</PrototypeNotice></div>;
}

export function PetsView() {
  const { state } = useHotel();
  const [query, setQuery] = useState('');
  const [activity, setActivity] = useState('Todas');
  const [lodging, setLodging] = useState('Todos');
  const records = state.pets.filter((item) => `${item.name} ${item.type} ${selectClientName(state, item.clientId)} ${item.lodgingPlace}`.toLowerCase().includes(query.toLowerCase()) && (activity === 'Todas' || (activity === 'Activas') === Boolean(state.stays.find((stay) => stay.id === item.stayId && stay.status === 'Activa'))) && (lodging === 'Todos' || (lodging === 'Habitación' ? item.lodgingPlace.includes('Habitación') : item.lodgingPlace.includes('cochera'))));
  return <div className="view-container"><PageHeader metadata="Propietario · estadía · cargo" title="Mascotas" description="Alojamiento, notas, habitación, reserva e incidencias por mascota activa o previa." /><MetricStrip items={[{ label: 'Registradas', value: state.pets.length }, { label: 'Con estadía activa', value: state.pets.filter((item) => state.stays.some((stay) => stay.id === item.stayId && stay.status === 'Activa')).length }, { label: 'En habitación', value: state.pets.filter((item) => item.lodgingPlace.includes('Habitación')).length }, { label: 'Cargos', value: formatMoney(state.pets.reduce((sum, item) => sum + item.charge, 0)) }, { label: 'Con incidencia', value: state.pets.filter((item) => item.damageIncidentId).length }]} /><div className="filter-bar"><label className="search-label"><Search size={16} /><input aria-label="Buscar mascotas" placeholder="Mascota, tipo, propietario o ubicación" value={query} onChange={(event) => setQuery(event.target.value)} /></label><label>Actividad<select value={activity} onChange={(event) => setActivity(event.target.value)}><option>Todas</option><option>Activas</option><option>Previas</option></select></label><label>Alojamiento<select value={lodging} onChange={(event) => setLodging(event.target.value)}><option>Todos</option><option>Habitación</option><option>Cochera</option></select></label></div><div className="operation-cards">{records.length ? records.map((pet) => { const stay = state.stays.find((item) => item.id === pet.stayId); const reservation = state.reservations.find((item) => item.id === stay?.reservationId); return <article className="card operation-card" key={pet.id}><div className="row-between"><div><span className="eyebrow">{pet.id} · {pet.type} · {pet.size}</span><h3>{pet.name}</h3></div><PawPrint size={22} aria-hidden="true" /></div><DetailGrid compact items={[{ label: 'Propietario', value: selectClientName(state, pet.clientId) }, { label: 'Actividad', value: stay?.status === 'Activa' ? 'Estadía activa' : 'Registro previo' }, { label: 'Estadía / reserva', value: pet.stayId || 'Sin estadía', detail: reservation?.id || 'Sin reserva' }, { label: 'Habitación', value: stay?.roomId || 'No asignada' }, { label: 'Alojamiento', value: pet.lodgingPlace }, { label: 'Cargo', value: formatMoney(pet.charge) }]} /><p>{pet.notes || 'Sin observaciones.'}</p><StatusBadge>{pet.damageIncidentId ? 'Con incidencia' : 'Sin daños'}</StatusBadge>{pet.damageIncidentId ? <small>Incidencia {pet.damageIncidentId}</small> : null}</article>; }) : <EmptyState />}</div></div>;
}

export function RecreationView({ notify }) {
  const { state, dispatch } = useHotel();
  const poolAccess = state.recreationAccess.filter((item) => item.zone === 'Piscina');
  const miradorAccess = state.recreationAccess.filter((item) => item.zone === 'Mirador');
  const poolInside = poolAccess.reduce((sum, item) => sum + item.peopleInside, 0);
  const [selectedAccess, setSelectedAccess] = useState(state.recreationAccess[0]?.id || '');
  const activeStays = state.stays.filter((item) => item.status === 'Activa');
  const [sale, setSale] = useState({ stayId: activeStays[0]?.id || '', zone: 'Piscina', allowedPeople: 1, amount: 30 });
  const duplicateSale = state.recreationAccess.some((item) => item.stayId === sale.stayId && item.zone === sale.zone && !['Finalizado', 'Vencido'].includes(item.status));
  const sell = () => { if (!sale.stayId || duplicateSale || Number(sale.allowedPeople) <= 0 || Number(sale.allowedPeople) > state.poolCapacity || Number(sale.amount) < 0) { notify('Acceso no vendido', duplicateSale ? 'La estadía ya tiene ese servicio habilitado.' : 'Revisá estadía, personas e importe.', 'error'); return; } executeWithFeedback(dispatch, { type: 'ACCESS_SELL', ...sale, allowedPeople: Number(sale.allowedPeople), amount: Number(sale.amount), requestId: `SALE-${sale.stayId}-${sale.zone}-${sale.allowedPeople}-${sale.amount}` }, notify, { title: 'Acceso habilitado', message: 'El servicio se cargó a cuenta y se generó una referencia QR interna. No se accionó hardware.' }); };
  const scan = (movement) => executeWithFeedback(dispatch, { type: 'ACCESS_SCAN', accessId: selectedAccess, movement, requestId: `SCAN-${selectedAccess}-${movement}-${Date.now()}` }, notify, { title: `Validación ${movement.toLowerCase()}`, message: 'El intento se registró localmente; no se abrió una valla física.', type: 'info' });
  const entries = state.accessLog.filter((item) => item.movement === 'Entrada' && item.result === 'Aprobado').length;
  const exits = state.accessLog.filter((item) => item.movement === 'Salida' && item.result === 'Aprobado').length;
  const rejected = state.accessLog.filter((item) => item.result === 'Rechazado').length;
  const manual = state.accessLog.filter((item) => item.reader?.toLowerCase().includes('manual')).length;
  return <div className="view-container"><PageHeader metadata="Piscina separada de Mirador" title="Zonas recreativas" description="Venta, QR, vigencia, pago, aforo de piscina y trazabilidad de accesos de la sesión." /><MetricStrip items={[{ label: 'Aforo piscina', value: `${poolInside}/${state.poolCapacity}` }, { label: 'Espacios piscina', value: state.poolCapacity - poolInside }, { label: 'Entradas registradas', value: entries }, { label: 'Salidas registradas', value: exits }, { label: 'Rechazos', value: rejected }, { label: 'Manuales', value: manual }]} /><div className="operations-grid"><section className="card"><SectionHeader eyebrow="Cuenta de estadía" title="Vender acceso" /><div className="form-grid"><label className="span-2">Estadía activa<select value={sale.stayId} onChange={(event) => setSale({ ...sale, stayId: event.target.value })}>{activeStays.map((stay) => <option key={stay.id} value={stay.id}>{stay.id} · Hab. {stay.roomId} · {selectClientName(state, stay.clientId)}</option>)}</select></label><label>Zona<select value={sale.zone} onChange={(event) => setSale({ ...sale, zone: event.target.value })}><option>Piscina</option><option>Mirador</option></select></label><label>Personas autorizadas<input type="number" min="1" max={state.poolCapacity} value={sale.allowedPeople} onChange={(event) => setSale({ ...sale, allowedPeople: event.target.value })} /></label><label className="span-2">Cargo a cuenta<input type="number" min="0" value={sale.amount} onChange={(event) => setSale({ ...sale, amount: event.target.value })} /></label><button className="btn btn-primary span-2" disabled={!activeStays.length || duplicateSale} onClick={sell}>{duplicateSale ? 'Servicio ya habilitado' : 'Cargar y habilitar QR'}</button></div></section><section className="card"><SectionHeader eyebrow="Sin hardware conectado" title="Validar movimiento QR" /><div className="form-grid"><label className="span-2">Acceso<select value={selectedAccess} onChange={(event) => setSelectedAccess(event.target.value)}>{state.recreationAccess.map((item) => <option key={item.id} value={item.id}>{item.id} · {item.zone} · Hab. {item.roomId} · {item.status}</option>)}</select></label><button className="btn btn-primary" disabled={!selectedAccess} onClick={() => scan('Entrada')}>Registrar entrada</button><button className="btn btn-outline" disabled={!selectedAccess} onClick={() => scan('Salida')}>Registrar salida</button></div><div className="alert-banner alert-banner-info">El check-out finaliza accesos de piscina y mirador y deja el QR inválido aunque el huésped conserve una copia.</div></section></div><section><SectionHeader eyebrow="Accesos vigentes" title="Piscina" description="Solo estos registros cuentan para el aforo de piscina." /><AccessCards records={poolAccess} state={state} /></section><section><SectionHeader eyebrow="Servicio independiente" title="Mirador" description="Sus accesos se muestran por separado y no consumen aforo de piscina." /><AccessCards records={miradorAccess} state={state} /></section><section><SectionHeader eyebrow="Sesión actual" title="Registro de validaciones" /><DataTable caption="Intentos de venta y movimientos QR de esta sesión" columns={['Fecha', 'Acceso', 'Estadía', 'Movimiento', 'Resultado', 'Motivo', 'Lector']}>{state.accessLog.length ? state.accessLog.map((item) => <tr key={item.id}><td>{formatDateTime(item.createdAt)}</td><td>{item.accessId || 'Sin acceso'}</td><td>{item.stayId}</td><td>{item.movement}</td><td><StatusBadge>{item.result}</StatusBadge></td><td>{item.reason || 'Validación aprobada'}</td><td>{item.reader}</td></tr>) : null}</DataTable></section><PrototypeNotice>la fecha actual no se persiste como historial diario. Lector, QR seguro y valla automática no están integrados.</PrototypeNotice></div>;
}

function AccessCards({ records, state }) {
  return records.length ? <div className="operation-cards">{records.map((access) => { const stay = state.stays.find((item) => item.id === access.stayId); return <article className="card operation-card" key={access.id}><div className="row-between"><div><span className="eyebrow">{access.id} · Hab. {access.roomId}</span><h3>{selectClientName(state, access.clientId)}</h3></div><StatusBadge>{access.status}</StatusBadge></div><DetailGrid compact items={[{ label: 'Estadía', value: access.stayId, detail: stay?.status }, { label: 'Pago', value: access.paid ? 'Confirmado' : 'Pendiente' }, { label: 'Vigencia', value: access.validUntil }, { label: 'Autorizados', value: access.allowedPeople }, { label: 'Dentro', value: access.peopleInside }, { label: 'Entradas', value: access.entries }]} /><small>{access.qrReference}</small></article>; })}</div> : <EmptyState title="Sin accesos para esta zona" />;
}

export function FoodBarView() {
  const { state } = useHotel();
  const [tab, setTab] = useState('recetas');
  const liquor = state.inventory.filter((item) => item.category === 'Licores');
  const currentOrders = state.orders.filter((item) => !['Pagado', 'Cancelado'].includes(item.status));
  return <div className="view-container"><PageHeader metadata="Costos y disponibilidad actual" title="Cocina y bar" description="Recetas, ingredientes, rentabilidad unitaria, pedidos activos y control de licores en onzas." /><MetricStrip items={[{ label: 'Pedidos activos', value: currentOrders.length }, { label: 'En preparación', value: currentOrders.filter((item) => item.status === 'En preparación').length }, { label: 'Recetas disponibles', value: state.recipes.filter((recipe) => recipe.ingredients.every((ingredient) => availableStock(state.inventory.find((item) => item.id === ingredient.inventoryId) || { stock: 0, reserved: 0 }) >= ingredient.quantity)).length }, { label: 'Stock bajo', value: state.inventory.filter((item) => availableStock(item) <= item.minimum).length }, { label: 'Onzas disponibles', value: liquor.reduce((sum, item) => sum + availableStock(item), 0).toFixed(1) }]} /><Tabs label="Cocina y bar" activeTab={tab} onChange={setTab} tabs={[{ id: 'recetas', label: 'Recetas' }, { id: 'licores', label: 'Licores' }, { id: 'pedidos', label: 'Pedidos activos' }, { id: 'turno', label: 'Turno' }]} /><TabPanel active={tab === 'recetas'} label="Recetas y rentabilidad"><div className="operation-cards">{state.recipes.map((recipe) => { const cost = recipe.ingredients.reduce((sum, ingredient) => { const item = state.inventory.find((entry) => entry.id === ingredient.inventoryId); return sum + (item?.cost || 0) * ingredient.quantity; }, 0); const servings = Math.max(0, Math.floor(Math.min(...recipe.ingredients.map((ingredient) => { const item = state.inventory.find((entry) => entry.id === ingredient.inventoryId); return availableStock(item || { stock: 0, reserved: 0 }) / ingredient.quantity; })))); const profit = recipe.salePrice - cost; const margin = recipe.salePrice ? (profit / recipe.salePrice) * 100 : 0; return <article className="card operation-card" key={recipe.id}><div className="row-between"><div><span className="eyebrow">{recipe.id} · {recipe.type}</span><h3>{recipe.name}</h3></div><StatusBadge>{servings > 0 ? 'Disponible' : 'No disponible'}</StatusBadge></div><div className="recipe-list">{recipe.ingredients.map((ingredient) => { const item = state.inventory.find((entry) => entry.id === ingredient.inventoryId); return <span key={ingredient.inventoryId}>{item?.name}<strong>{ingredient.quantity} {item?.unit} · disp. {availableStock(item || { stock: 0, reserved: 0 })}</strong></span>; })}</div><DetailGrid compact items={[{ label: 'Costo', value: formatMoney(cost) }, { label: 'Venta', value: formatMoney(recipe.salePrice) }, { label: 'Ganancia unitaria', value: formatMoney(profit) }, { label: 'Margen', value: `${margin.toFixed(1)} %` }, { label: 'Porciones disponibles', value: servings }, { label: 'Pedidos activos', value: currentOrders.filter((order) => order.items.some((item) => item.recipeId === recipe.id)).length }]} /></article>; })}</div></TabPanel><TabPanel active={tab === 'licores'} label="Licores en onzas"><div className="kpi-grid-4"><Kpi label="Físico" value={`${liquor.reduce((sum, item) => sum + item.stock, 0).toFixed(1)} oz`} icon={Beer} /><Kpi label="Reservado" value={`${liquor.reduce((sum, item) => sum + item.reserved, 0).toFixed(1)} oz`} /><Kpi label="Disponible" value={`${liquor.reduce((sum, item) => sum + availableStock(item), 0).toFixed(1)} oz`} /><Kpi label="Valor disponible" value={formatMoney(liquor.reduce((sum, item) => sum + availableStock(item) * item.cost, 0))} /></div><DataTable caption="Control de licores disponible en el inventario actual" columns={['Licor', 'Lote', 'Físico', 'Reservado', 'Disponible', 'Costo/oz', 'Valor disponible', 'Estado']}>{liquor.length ? liquor.map((item) => <tr key={item.id}><td><strong>{item.name}</strong><br /><small>{item.id}</small></td><td>{item.lot}</td><td>{item.stock} oz</td><td>{item.reserved} oz</td><td>{availableStock(item).toFixed(1)} oz</td><td>{formatMoney(item.cost)}</td><td>{formatMoney(availableStock(item) * item.cost)}</td><td><StatusBadge>{availableStock(item) <= item.minimum ? 'Bajo mínimo' : 'Óptimo'}</StatusBadge></td></tr>) : null}</DataTable></TabPanel><TabPanel active={tab === 'pedidos'} label="Pedidos activos"><div className="record-list">{currentOrders.map((item) => <article key={item.id}><div><strong>{item.id} · {item.items.map((entry) => `${entry.quantity}× ${entry.name}`).join(', ')}</strong><span>{item.source} · ETA {item.estimatedMinutes} min · {item.inventoryStage}</span></div><StatusBadge>{item.status}</StatusBadge></article>)}</div></TabPanel><TabPanel active={tab === 'turno'} label="Resumen del turno"><section className="card"><SectionHeader eyebrow="Solo sesión actual" title="Control referencial" /><DetailGrid items={[{ label: 'Pedidos cargados', value: state.orders.length }, { label: 'Pedidos pagados', value: state.orders.filter((item) => item.status === 'Pagado').length }, { label: 'Pedidos cancelados', value: state.orders.filter((item) => item.status === 'Cancelado').length }, { label: 'Recetas', value: state.recipes.length }, { label: 'Productos reservados', value: state.inventory.filter((item) => item.reserved > 0).length }, { label: 'Valor disponible', value: formatMoney(state.inventory.reduce((sum, item) => sum + availableStock(item) * item.cost, 0)) }]} /><PrototypeNotice>no existen apertura/cierre persistentes, conteo físico, mermas, cortesías ni históricos por bartender. No se presentan como resultados diarios.</PrototypeNotice></section></TabPanel></div>;
}

export function SuppliersView() {
  const { state } = useHotel();
  const [query, setQuery] = useState('');
  const [primary, setPrimary] = useState('Todos');
  const [category, setCategory] = useState('Todas');
  const [delivery, setDelivery] = useState('Todos');
  const records = state.suppliers.filter((item) => `${item.businessName} ${item.ruc} ${item.contact} ${item.products.join(' ')}`.toLowerCase().includes(query.toLowerCase()) && (primary === 'Todos' || item.primary === (primary === 'Principal')) && (category === 'Todas' || item.products.includes(category)) && (delivery === 'Todos' || (delivery === '1 día' ? item.averageDeliveryDays <= 1 : item.averageDeliveryDays > 1)));
  return <div className="view-container"><PageHeader metadata="Proveedor e inventario vinculados" title="Proveedores" description="Contacto, categorías, entrega y riesgo de abastecimiento por producto, lote y vencimiento." /><MetricStrip items={[{ label: 'Proveedores', value: state.suppliers.length }, { label: 'Principales', value: state.suppliers.filter((item) => item.primary).length }, { label: 'Productos vinculados', value: state.inventory.filter((item) => item.supplierId).length }, { label: 'Productos en riesgo', value: state.inventory.filter((item) => availableStock(item) <= item.minimum).length }]} /><div className="filter-bar"><label className="search-label"><Search size={16} /><input aria-label="Buscar proveedores" placeholder="Razón social, RUC, contacto o categoría" value={query} onChange={(event) => setQuery(event.target.value)} /></label><label>Relación<select value={primary} onChange={(event) => setPrimary(event.target.value)}><option>Todos</option><option>Principal</option><option>Alternativo</option></select></label><label>Categoría<select value={category} onChange={(event) => setCategory(event.target.value)}><option>Todas</option>{[...new Set(state.suppliers.flatMap((item) => item.products))].map((item) => <option key={item}>{item}</option>)}</select></label><label>Entrega<select value={delivery} onChange={(event) => setDelivery(event.target.value)}><option>Todos</option><option>1 día</option><option>Más de 1 día</option></select></label></div><div className="operation-cards">{records.length ? records.map((supplier) => { const products = state.inventory.filter((item) => item.supplierId === supplier.id); const risk = products.filter((item) => availableStock(item) <= item.minimum); return <article className="card operation-card" key={supplier.id}><div className="row-between"><div><span className="eyebrow">{supplier.id} · RUC {supplier.ruc}</span><h3>{supplier.businessName}</h3></div>{supplier.primary ? <span className="badge badge-gold">Principal</span> : <StatusBadge>Alternativo</StatusBadge>}</div><DetailGrid compact items={[{ label: 'Contacto', value: supplier.contact }, { label: 'Teléfono', value: supplier.phone }, { label: 'Correo', value: supplier.email }, { label: 'Entrega promedio', value: `${supplier.averageDeliveryDays} día(s)` }, { label: 'Productos vinculados', value: products.length }, { label: 'En riesgo', value: risk.length }]} /><div className="supplier-products">{products.map((item) => <div key={item.id}><span><strong>{item.name}</strong><small>{item.lot} · vence {item.expiresAt || 'no aplica'}</small></span><span>{availableStock(item)} {item.unit}<small>{formatMoney(item.cost)} / {item.unit} · valor {formatMoney(availableStock(item) * item.cost)}</small></span><StatusBadge>{availableStock(item) <= item.minimum ? 'Bajo mínimo' : 'Óptimo'}</StatusBadge></div>)}</div></article>; }) : <EmptyState />}</div></div>;
}

export function IncidentsView({ notify }) {
  const { state, dispatch } = useHotel();
  const [priority, setPriority] = useState('Todas');
  const [status, setStatus] = useState('Todos');
  const [type, setType] = useState('Todos');
  const [roomId, setRoomId] = useState('Todas');
  const records = state.incidents.filter((item) => (priority === 'Todas' || item.priority === priority) && (status === 'Todos' || item.status === status) && (type === 'Todos' || item.type === type) && (roomId === 'Todas' || item.roomId === roomId));
  return <div className="view-container"><PageHeader metadata="Cola unificada" title="Incidencias" description="Prioridad, origen, referencia, evidencia, responsable, solución y próximo estado explícito." /><MetricStrip items={[{ label: 'Abiertas', value: state.incidents.filter((item) => !['Resuelta', 'Cerrada'].includes(item.status)).length }, { label: 'Pendientes', value: state.incidents.filter((item) => item.status === 'Pendiente').length }, { label: 'En proceso', value: state.incidents.filter((item) => item.status === 'En proceso').length }, { label: 'Urgentes', value: state.incidents.filter((item) => item.priority === 'Urgente').length }, { label: 'Con evidencia', value: state.incidents.filter((item) => item.evidence.length).length }]} /><div className="filter-bar"><label>Prioridad<select value={priority} onChange={(event) => setPriority(event.target.value)}><option>Todas</option><option>Baja</option><option>Media</option><option>Alta</option><option>Urgente</option></select></label><label>Estado<select value={status} onChange={(event) => setStatus(event.target.value)}><option>Todos</option><option>Pendiente</option><option>Asignada</option><option>En proceso</option><option>Resuelta</option><option>Cerrada</option></select></label><label>Tipo<select value={type} onChange={(event) => setType(event.target.value)}><option>Todos</option>{[...new Set(state.incidents.map((item) => item.type))].map((item) => <option key={item}>{item}</option>)}</select></label><label>Habitación<select value={roomId} onChange={(event) => setRoomId(event.target.value)}><option>Todas</option>{[...new Set(state.incidents.map((item) => item.roomId).filter(Boolean))].map((item) => <option key={item}>{item}</option>)}</select></label></div><div className="operation-cards">{records.length ? records.map((incident) => { const maintenance = state.maintenanceTickets.find((item) => item.id === incident.referenceId); const next = nextIncidentStatus(incident.status); return <article className="card operation-card" key={incident.id}><div className="row-between"><div><span className="eyebrow">{incident.id} · {incident.type}</span><h3>{incident.description}</h3></div><StatusBadge>{incident.priority}</StatusBadge></div><DetailGrid compact items={[{ label: 'Habitación', value: incident.roomId || 'No aplica' }, { label: 'Responsable', value: incident.responsible }, { label: 'Referencia', value: incident.referenceId || 'Sin referencia' }, { label: 'Mantenimiento', value: maintenance?.id || 'No vinculado', detail: maintenance?.status }, { label: 'Evidencia', value: `${incident.evidence.length} referencia(s)` }, { label: 'Solución', value: incident.solution || 'Pendiente' }]} /><div className="row-between"><StatusBadge>{incident.status}</StatusBadge>{next ? <button className="btn btn-sm btn-primary" onClick={() => { dispatch({ type: 'INCIDENT_PROGRESS', incidentId: incident.id, expectedStatus: incident.status }); notify('Incidencia actualizada', `Estado siguiente: ${next}.`); }}>Avanzar a {next}</button> : <span className="muted-block">Flujo cerrado</span>}</div></article>; }) : <EmptyState />}</div></div>;
}

export function SurveysView({ notify }) {
  const { state } = useHotel();
  const [status, setStatus] = useState('Todos');
  const records = state.surveys.filter((item) => status === 'Todos' || item.status === status);
  const answered = state.surveys.filter((item) => item.status === 'Respondida');
  const average = (field) => answered.length ? answered.reduce((sum, item) => sum + (item[field] || 0), 0) / answered.length : 0;
  return <div className="view-container"><PageHeader metadata="Seguimiento posterior" title="Encuestas y fidelización" description="Dimensiones de satisfacción, comentario, consentimiento, cliente y estadía de referencia." /><MetricStrip items={[{ label: 'Encuestas', value: state.surveys.length }, { label: 'Respondidas', value: answered.length }, { label: 'Tasa de respuesta', value: state.surveys.length ? `${Math.round((answered.length / state.surveys.length) * 100)} %` : '0 %' }, { label: 'Promedio general', value: `${average('overall').toFixed(1)}/5` }, { label: 'Promociones autorizadas', value: state.surveys.filter((item) => item.promotionsAuthorized).length }]} /><div className="filter-bar"><label>Estado<select value={status} onChange={(event) => setStatus(event.target.value)}><option>Todos</option><option>Pendiente</option><option>Respondida</option></select></label><span className="filter-result">{records.length} encuestas</span></div><div className="operations-grid"><section className="card"><SectionHeader eyebrow="Dimensiones respondidas" title="Promedios visibles" /><DetailGrid items={[{ label: 'General', value: `${average('overall').toFixed(1)} / 5` }, { label: 'Limpieza', value: `${average('cleaning').toFixed(1)} / 5` }, { label: 'Atención', value: `${average('service').toFixed(1)} / 5` }, { label: 'Habitación', value: `${average('room').toFixed(1)} / 5` }, { label: 'Comida', value: `${average('food').toFixed(1)} / 5` }]} /></section><section className="card"><SectionHeader eyebrow="Programa frecuente" title="Resumen de fidelización" /><div className="summary-list static">{state.clients.toSorted((a, b) => b.loyaltyPoints - a.loyaltyPoints).map((client) => <span key={client.id}><span><strong>{client.name}</strong><small>{client.visits} estadías · {formatMoney(client.totalSpent)} · promociones {client.promoAuth ? 'sí' : 'no'}</small></span><span className="badge badge-gold">{client.loyaltyTier} · {client.loyaltyPoints} pts</span></span>)}</div></section></div><div className="survey-grid">{records.map((survey) => <article className="card" key={survey.id}><div className="row-between"><div><span className="eyebrow">{survey.id} · enviada {survey.sentAt}</span><h3>{selectClientName(state, survey.clientId)}</h3></div><StatusBadge>{survey.status}</StatusBadge></div><DetailGrid compact items={[{ label: 'Estadía', value: survey.stayId || 'No vinculada' }, { label: 'General', value: survey.overall ? `${survey.overall}/5` : 'Pendiente' }, { label: 'Limpieza', value: survey.cleaning ? `${survey.cleaning}/5` : 'Pendiente' }, { label: 'Atención', value: survey.service ? `${survey.service}/5` : 'Pendiente' }, { label: 'Habitación', value: survey.room ? `${survey.room}/5` : 'Pendiente' }, { label: 'Comida', value: survey.food ? `${survey.food}/5` : 'Pendiente' }, { label: 'Promociones', value: survey.promotionsAuthorized ? 'Autorizadas' : 'No autorizadas' }]} /><p>{survey.comment || 'Sin comentario o respuesta todavía.'}</p></article>)}</div><button className="btn btn-outline" onClick={() => notify('Envío no realizado', 'Correo y WhatsApp no están integrados; no se modificó el estado.', 'info')}>Revisar recordatorio externo no disponible</button></div>;
}

export function RolesView() {
  const { state } = useHotel();
  const modules = ['Todos los módulos', 'Clientes', 'Reservas', 'Check-in/out', 'Pagos', 'Tareas asignadas', 'Evidencias', 'Incidencias', 'Pedidos', 'Recetas', 'Inventario relacionado', 'Configuración', 'Auditoría'];
  const specifiedRoles = ['Administrador', 'Recepcionista', 'Limpieza', 'Cocina', 'Bar', 'Contabilidad', 'Mantenimiento', 'Seguridad'];
  return <div className="view-container"><PageHeader metadata="Matriz informativa, no enforcement" title="Roles y permisos" description="Comparación de usuarios, cobertura modular y roles indicados por la especificación aún no configurados." /><MetricStrip items={[{ label: 'Roles configurados', value: state.roles.length }, { label: 'Usuarios declarados', value: state.roles.reduce((sum, item) => sum + item.users, 0) }, { label: 'Módulos comparados', value: modules.length }, { label: 'Roles de especificación pendientes', value: specifiedRoles.filter((item) => !state.roles.some((role) => role.name === item)).length }]} /><section className="card table-container"><table className="custom-table permission-table"><caption>Matriz comparativa de permisos declarados</caption><thead><tr><th scope="col">Módulo o alcance</th>{state.roles.map((role) => <th scope="col" key={role.id}>{role.name}<small>{role.users} usuario(s)</small></th>)}</tr></thead><tbody>{modules.map((module) => <tr key={module}><th scope="row">{module}</th>{state.roles.map((role) => { const granted = role.permissions.includes('Todos los módulos') || role.permissions.includes(module); return <td key={role.id}><span className={`permission-mark ${granted ? 'granted' : 'not-granted'}`}>{granted ? 'Permitido' : 'No declarado'}</span></td>; })}</tr>)}</tbody></table></section><section className="card"><SectionHeader eyebrow="Referencia de la especificación" title="Roles aún no configurados" /><div className="chip-row">{specifiedRoles.filter((item) => !state.roles.some((role) => role.name === item)).map((item) => <span className="chip" key={item}>{item}</span>)}</div><p className="muted-block">Estos nombres son una referencia estática del documento. No se crearon roles ficticios ni permisos ejecutables.</p></section><PrototypeNotice>la matriz no protege rutas ni datos. La autorización real requiere autenticación y validación del lado servidor.</PrototypeNotice></div>;
}

export function AuditView({ navigate }) {
  const { state } = useHotel();
  const [query, setQuery] = useState('');
  const [module, setModule] = useState('Todos');
  const [user, setUser] = useState('Todos');
  const auditEntries = state.auditLog.map((item) => ({ ...item, kind: 'Operación' }));
  const accessEntries = state.accessLog.map((item) => ({ id: `AUD-${item.id}`, user: item.reader, action: `${item.movement} ${item.result}`, module: 'Zonas recreativas', recordId: item.accessId || item.stayId, createdAt: item.createdAt, detail: item.reason || 'Validación aprobada', kind: 'Acceso QR' }));
  const records = [...auditEntries, ...accessEntries].filter((item) => `${item.user} ${item.action} ${item.module} ${item.recordId} ${item.detail}`.toLowerCase().includes(query.toLowerCase()) && (module === 'Todos' || item.module === module) && (user === 'Todos' || item.user === user)).toSorted((a, b) => b.createdAt.localeCompare(a.createdAt));
  return <div className="view-container"><PageHeader metadata="Más reciente primero · sin mutar estado" title="Auditoría y seguridad" description="Actividad operativa y accesos QR diferenciados, con filtros y enlaces seguros a módulos." /><MetricStrip items={[{ label: 'Operaciones', value: auditEntries.length }, { label: 'Accesos QR', value: accessEntries.length }, { label: 'Usuarios / lectores', value: new Set([...auditEntries, ...accessEntries].map((item) => item.user)).size }, { label: 'Módulos', value: new Set(auditEntries.map((item) => item.module)).size }, { label: 'Rechazos QR', value: state.accessLog.filter((item) => item.result === 'Rechazado').length }]} /><div className="filter-bar"><label className="search-label"><Search size={16} /><input aria-label="Buscar auditoría" placeholder="Usuario, acción, módulo o registro" value={query} onChange={(event) => setQuery(event.target.value)} /></label><label>Módulo<select value={module} onChange={(event) => setModule(event.target.value)}><option>Todos</option>{[...new Set([...auditEntries, ...accessEntries].map((item) => item.module))].map((item) => <option key={item}>{item}</option>)}</select></label><label>Actor<select value={user} onChange={(event) => setUser(event.target.value)}><option>Todos</option>{[...new Set([...auditEntries, ...accessEntries].map((item) => item.user))].map((item) => <option key={item}>{item}</option>)}</select></label></div><DataTable caption="Actividad operativa y validaciones de acceso de la sesión" columns={['Fecha', 'Tipo', 'Usuario / lector', 'Acción', 'Módulo', 'Registro', 'Detalle', 'Destino']}>{records.length ? records.map((item) => <tr key={`${item.kind}-${item.id}`}><td>{formatDateTime(item.createdAt)}</td><td><span className="badge badge-gray">{item.kind}</span></td><td>{item.user}</td><td>{item.action}</td><td>{item.module}</td><td>{item.recordId}</td><td>{item.detail}</td><td>{moduleRoutes[item.module] ? <button className="btn btn-sm btn-outline" onClick={() => navigate(moduleRoutes[item.module])}>Abrir</button> : 'Sin enlace seguro'}</td></tr>) : null}</DataTable><PrototypeNotice>este log vive en memoria y no es inmutable ni seguro frente a manipulación del navegador.</PrototypeNotice></div>;
}

export function SettingsView() {
  const { state } = useHotel();
  const groups = [
    { name: 'Mensajería', ids: ['INT-MSG'] },
    { name: 'Fiscal', ids: ['INT-FISCAL'] },
    { name: 'Hardware', ids: ['INT-POOL'] },
    { name: 'Seguridad', ids: ['INT-AUTH'] },
    { name: 'Almacenamiento', ids: ['INT-BACKUP'] },
  ];
  const pending = state.integrations.filter((item) => item.status.includes('Pendiente')).length;
  const unconfigured = state.integrations.filter((item) => item.status.includes('No configurado')).length;
  return <div className="view-container"><PageHeader metadata="Referencia operativa de solo lectura" title="Configuración" description="Integraciones agrupadas y parámetros codificados actualmente en el prototipo." /><MetricStrip items={[{ label: 'Integraciones', value: state.integrations.length }, { label: 'Pendientes', value: pending }, { label: 'No configuradas', value: unconfigured }, { label: 'Operativas externas', value: 0 }]} /><section className="settings-hero"><div><span className="eyebrow">Hotel Park Plaza</span><h3>Parámetros visibles</h3><p>38 habitaciones · 4 pisos · moneda PEN · capacidad piscina {state.poolCapacity}</p></div><StatusBadge>Pendiente de backend</StatusBadge></section><div className="settings-groups">{groups.map((group) => <section key={group.name} aria-labelledby={`settings-${group.name}`}><SectionHeader id={`settings-${group.name}`} eyebrow="Integraciones" title={group.name} /><div className="integration-grid">{state.integrations.filter((item) => group.ids.includes(item.id)).map((item) => <article className="card integration-card" key={item.id}><div className="row-between"><div className="integration-icon"><AlertTriangle size={20} aria-hidden="true" /></div><StatusBadge>{item.status}</StatusBadge></div><h3>{item.name}</h3><p>{item.detail}</p><button className="btn btn-outline" disabled>Configuración no disponible</button></article>)}</div></section>)}</div><section className="card"><SectionHeader eyebrow="Valores codificados" title="Referencia del dominio actual" description="Estos valores provienen del código del prototipo, no de una consola de configuración persistente." /><div className="reference-groups"><article><strong>Hotel</strong><span>38 habitaciones · pisos 1–4 · PEN</span></article><article><strong>Categorías</strong><span>{ROOM_CATEGORIES.join(', ')}</span></article><article><strong>Estados de habitación</strong><span>{ROOM_STATUSES.join(', ')}</span></article><article><strong>Pagos</strong><span>{PAYMENT_METHODS.join(', ')}</span></article><article><strong>Piscina</strong><span>Capacidad codificada: {state.poolCapacity} personas</span></article><article><strong>Penalidades activas</strong><span>{PENALTIES.filter((item) => item.active).length} referencias codificadas en dominio; no editables desde esta UI.</span></article></div></section><section className="card"><SectionHeader eyebrow="Persistencia" title="Copias de seguridad" /><div className="backup-status"><div><strong>Sin respaldo configurado</strong><span>El frontend pierde cambios al recargar y no crea archivos de respaldo.</span></div><button className="btn btn-outline" disabled>Respaldo no disponible</button></div></section></div>;
}
